1:import Link from "next/link";
2:import type { Metadata } from "next";
3:import { GameLandingCombined } from "@/components/marketing/gamelanding/GameLandingCombined";
4:import { PREVIEW_GAMES } from "@/components/marketing/gamelanding/data";
5:import { ReviewBadges } from "@/components/marketing/ReviewBadges";
6:import { Section, SectionTitle } from "@/components/marketing/primitives";
7:import { FaqJsonLd, ProductOffersJsonLd, APP_URL } from "@/components/marketing/StructuredData";

1	import { headers } from "next/headers";
2	import { db } from "@/lib/db";
3	import { requireUser } from "@/lib/auth";
4	import { clientIp } from "@/lib/rate-limit";
5	import { hashIp } from "@/lib/coupon-order";
6	import { firstMonthFreeEligible, firstMonthFreeEnabled, firstMonthFreeAppliesTo } from "@/lib/promo-redemption";
7	import { annualDiscountPct } from "@/lib/annual-discount";
8	import { extraDiskPerGbCents } from "@/lib/disk-expand";
9	import { dedicatedIpMonthlyCents } from "@/lib/dedicated-ip";
10	import { backupPlusMonthlyCents } from "@/lib/backup-upgrade";
11	import { VPS_TERMS, vpsTermPriceCents, termPriceCents, termDiscountPct } from "@/lib/billing-terms";
12	import { regionsFrom, appSpriteKey, gameArt } from "@/lib/nx/catalog";
13	import { GAME_DISPLAY, GAME_GENRES, HOSTNAME_CONNECT_FAMILIES, type GameFamily } from "@/lib/games";
14	import { GAME_CONFIG_SCHEMAS } from "@/lib/game-config";
15	import { GAME_FAMILIES } from "@/lib/games";
16	import { stripeConfigured } from "@/lib/stripe";
17	import { paypalConfigured } from "@/lib/paypal";
18	import { coinbaseConfigured } from "@/lib/coinbase-commerce";
19	import { DeployView } from "@/components/nx/DeployView";
20	import type { AddonOption, EmailPlanOption, GameFamilyOption, HostingPlanOption, OsOption, PlanOption, TermOption } from "@/components/nx/order-types";
21	
22	/* Data for the VPS deploy wizard.
23	 *
24	 * The one rule this file exists to keep: every number the wizard can display is
25	 * computed HERE, by the same functions that charge the card, and handed down
26	 * already worked out. The view prints; it never multiplies.
27	 *
28	 * `effectiveMonthlyCents` is built as a plan x term MATRIX rather than sent as a
29	 * rate plus a discount percent. Sending the percent would mean the browser does
30	 * `rate * (1 - pct)` — a second pricing formula, and the one that is on screen
31	 * when the customer decides. Terms are few and plans are few, so the matrix is
32	 * cheap and it cannot drift from `vpsTermPriceCents`.
33	 */
34	
35	export const dynamic = "force-dynamic";
36	
37	/* Icon per image, keyed off the platform's own `family` value rather than
38	   sniffing the display name. Control panels and applications have families too
39	   (cpanel, plesk, docker, ...), so one map serves all three tabs. */
40	const ICON_BY_FAMILY: Record<string, string> = {
41	  ubuntu: "ubuntu", debian: "debian", almalinux: "osA", rocky: "osC",
42	  arch: "arch", fedora: "osB", windows: "windows", centos: "osA",
43	  docker: "docker", wordpress: "cloud", node: "nginx", nginx: "nginx",
44	  mysql: "mysql", postgres: "postgres", redis: "redis",
45	  cpanel: "gear2", plesk: "gear2", webmin: "sliders", hestiacp: "sliders",
46	  cloudpanel: "sliders", cyberpanel: "sliders", aapanel: "sliders",
47	};
48	function osIcon(family: string, category: string): string {
49	  return ICON_BY_FAMILY[family?.toLowerCase()]
50	    ?? (category === "CONTROL_PANEL" ? "sliders" : category === "APPLICATION" ? "cube" : "linux");
51	}
52	
53	export default async function NxDeployPage() {
54	  const user = await requireUser();
55	
56	  // Real, per-customer eligibility for the first-month-free hosting promo —
57	  // NOT a display detail, the exact same advisory pre-check
58	  // lib/actions-hosting.ts runs before the atomic claim at charge time. The
59	  // wizard's hosting/email price was a flat, precomputed matrix with zero
60	  // per-user awareness (deliberately: "so there is no round-trip to make"),
61	  // which is why the promo's own plan-card badge ("First month free") and
62	  // the wizard's actual total disagreed — the matrix could not have known
63	  // whether THIS customer still qualifies. One extra check here, resolved
64	  // alongside the rest of this page's own data fetching.
65	  const hostingPromoIpHash = hashIp(clientIp(await headers()), process.env.AUTH_SECRET ?? "nxeon") || null;
66	  const hostingPromoEligible =
67	    firstMonthFreeAppliesTo("HOSTING") &&
68	    (await firstMonthFreeEnabled()) &&
69	    (await firstMonthFreeEligible(user.id, hostingPromoIpHash));
70	
71	  const [plans, oses, nodes, gamePlans, hostingPlans, emailPlans, annualPct, diskPerGbCents, ipCents, backupCents] = await Promise.all([
72	    db.plan.findMany({ where: { active: true }, orderBy: { priceCents: "asc" } }),
73	    /* All three categories — the design's Server settings panel has a tab per
74	       category (Operating system / Control panels / Applications), which is
75	       exactly what ImageCategory already distinguishes. They are separated in
76	       the VIEW, not filtered out here: a game-server image is a real thing you
77	       can deploy, it just is not an answer to "pick an operating system". */
78	    /* Game images are EXCLUDED from the VPS wizard. They are real deployable
79	       images, but Nxeon sells game servers as their own product with their own
80	       plans, panel and pricing — offering "Minecraft Server" as a VPS
81	       application sells the same thing twice, at the wrong price, without the
82	       game panel. Identified by `family` against the platform's own
83	       GAME_FAMILIES registry rather than by matching "... Server" in a name. */
84	    db.osTemplate.findMany({
85	      where: { active: true, NOT: { family: { in: [...GAME_FAMILIES] } } },
86	      orderBy: [{ sortOrder: "asc" }, { name: "asc" }],
87	    }),
88	    // enabled only — a disabled node is not a place we can provision.
89	    db.node.findMany({ where: { enabled: true }, select: { id: true, region: true } }),
90	    // "from" prices for the service tiles — the cheapest live plan of each kind,
91	    // read from the same tables the order path prices against.
92	    // Every active tier: the wizard groups them into families itself, so one
93	    // query serves both the "from" price on the tiles and the tier picker.
94	    db.gamePlan.findMany({ where: { active: true }, orderBy: { priceCents: "asc" } }),
95	    db.hostingPlan.findMany({ where: { active: true }, orderBy: { priceCents: "asc" } }),
96	    db.emailPlan.findMany({ where: { active: true }, orderBy: [{ sortOrder: "asc" }, { priceCents: "asc" }] }),
97	    annualDiscountPct(),
98	    extraDiskPerGbCents(),
99	    dedicatedIpMonthlyCents(),
100	    backupPlusMonthlyCents(),
101	  ]);
102	
103	  /* The monthly term is the reference rate the cards show by default; the wizard
104	     re-reads this matrix when the customer changes term. Priced through
105	     `vpsTermPriceCents`, the same helper `orderQuote` uses. */
106	  const priceMatrix: Record<string, Record<number, number>> = {};
107	  for (const p of plans) {
108	    priceMatrix[p.id] = {};
109	    for (const t of VPS_TERMS) {
110	      // term total / months = the effective monthly rate at that term
111	      priceMatrix[p.id][t.months] = Math.round(
112	        vpsTermPriceCents(p.priceCents, t.months, annualPct) / t.months
113	      );
114	    }
115	  }
116	
117	  /* "Recommended" is the middle of the ladder, not the most expensive — the
118	     default has to be a defensible choice, not an upsell. */
119	  const recommendedId = plans.length ? plans[Math.floor((plans.length - 1) / 2)].id : null;
120	
121	  const planOptions: PlanOption[] = plans.map((p) => ({
122	    id: p.id,
123	    slug: p.slug,
124	    name: p.name,
125	    cpuCores: p.cpuCores,
126	    ramMB: p.ramMB,
127	    diskGB: p.diskGB,
128	    bandwidthTB: p.bandwidthTB,
129	    monthlyCents: p.priceCents,
130	    effectiveMonthlyCents: priceMatrix[p.id][1],
131	    introMonthlyCents: p.introPriceCents ?? null,
132	    introRenewalMonthlyCents: p.introPriceCents ? p.priceCents : null,
133	    recommended: p.id === recommendedId,
134	  }));
135	
136	  const osOptions: OsOption[] = oses.map((o) => ({
137	    id: o.id,
138	    name: o.name,
139	    version: o.version ?? "",
140	    icon: osIcon(o.family, o.category),
141	    category: o.category,
142	    family: o.family,
143	    spriteKey: o.category === "PLAIN_OS" ? null : appSpriteKey(o.name),
144	  }));
145	
146	  const termOptions: TermOption[] = VPS_TERMS.map((t) => ({
147	    months: t.months,
148	    label: t.label,
149	    discountPercent: termDiscountPct(t.months, annualPct),
150	  }));
151	
152	  /* Add-on rates come from the same functions the charge path reads. A rate
153	     hardcoded next to a checkbox is how a display price and a charged price
154	     drift apart. */
155	  /* Families are built from the tiers that actually exist. A family with no
156	     active plan is not offered — the alternative is a card that leads to an
157	     empty tier list. Variants and the subdomain requirement come from the
158	     platform's own family schema, not from a list kept here. */
159	  // Leads the game grid, in this order, each badged "Popular" — the owner's
160	  // pick, not a computed ranking (no real play-count/order-volume signal
161	  // exists yet to rank by). `projectzomboid`/`sdtd` are the actual family
162	  // keys behind "Project Zomboid" / "7 Days to Die" (lib/games.ts
163	  // GAME_FAMILIES) — the display names aren't the lookup keys.
164	  const POPULAR_GAME_ORDER = ["minecraft", "rust", "valheim", "palworld", "projectzomboid", "terraria"];
165	  const gameFamilies: GameFamilyOption[] = (() => {
166	    const byFamily = new Map<string, typeof gamePlans>();
167	    for (const gp of gamePlans) {
168	      const list = byFamily.get(gp.gameFamily) ?? [];
169	      list.push(gp);
170	      byFamily.set(gp.gameFamily, list);
171	    }
172	    return [...byFamily.entries()].map(([family, tiers]) => {
173	      const schema = GAME_CONFIG_SCHEMAS[family];
174	      return {
175	        family,
176	        name: GAME_DISPLAY[family as keyof typeof GAME_DISPLAY]?.name ?? family,
177	        art: gameArt(family),
178	        variants: schema?.variants ?? [],
179	        defaultVariant: schema?.defaultVariant ?? "",
180	        genres: GAME_GENRES[family as keyof typeof GAME_GENRES] ?? [],
181	        /* Same source of truth quoteGameOrder (lib/game-order.ts) charges
182	           through — a second, hand-maintained "just minecraft" check here
183	           silently left every other hostname-connect family (ARK, the
184	           Source-engine titles, Satisfactory, Conan, 7 Days to Die,
185	           Enshrouded, and more) without a "Play address" field to fill in,
186	           so their orders could reach the payment step with no subdomain
187	           and no way to price. */
188	        needsSubdomain: family === "minecraft" || family === "bedrock"
189	          || HOSTNAME_CONNECT_FAMILIES.has(family as GameFamily),
190	        fromCents: Math.min(...tiers.map((t) => t.priceCents)),
191	        popular: POPULAR_GAME_ORDER.includes(family),
192	        tiers: tiers.map((t) => ({
193	          id: t.id,
194	          name: t.name,
195	          ramMB: t.ramMB,
196	          cpuCores: t.cpuCores,
197	          diskGB: t.diskGB,
198	          slots: t.slots ?? null,
199	          monthlyCents: t.priceCents,
200	          termMonths: t.termMonths,
201	        })),
202	      };
203	    }).sort((a, b) => {
204	      const pa = POPULAR_GAME_ORDER.indexOf(a.family);
205	      const pb = POPULAR_GAME_ORDER.indexOf(b.family);
206	      if (pa !== -1 || pb !== -1) return (pa === -1 ? 999 : pa) - (pb === -1 ? 999 : pb);
207	      return a.name.localeCompare(b.name);
208	    });
209	  })();
210	
211	  const hostingOptions: HostingPlanOption[] = hostingPlans.map((h) => ({
212	    id: h.id, name: h.name, tagline: h.tagline,
213	    diskGB: h.diskGB, maxSites: h.maxSites, maxDatabases: h.maxDatabases,
214	    bandwidthTB: h.bandwidthTB, mailboxes: h.mailboxes,
215	    freeMigration: h.freeMigration, featured: h.featured,
216	    monthlyCents: h.priceCents,
217	  }));
218	
219	  const emailOptions: EmailPlanOption[] = emailPlans.map((e) => ({
220	    id: e.id, name: e.name, mailboxes: e.mailboxes,
221	    storageGB: e.storageGB, monthlyCents: e.priceCents, termMonths: e.termMonths,
222	  }));
223	
224	  /* Hosting and email price through `termPriceCents` — the same helper their
225	     own charge paths use (lib/actions-hosting.ts, lib/actions-email-hosting.ts).
226	     Built as a matrix for the same reason as the VPS one: sending a rate and a
227	     discount percent would put the multiply back in the browser. */
228	  const hostingMatrix: Record<string, Record<number, number>> = {};
229	  // The real term total — `termPriceCents` unrounded-and-redivided — for the
230	  // checkout math. hostingMatrix above rounds THIS down to a per-month rate
231	  // for display ("$X/mo" labels), which is a real, separate rounding step:
232	  // re-multiplying that rounded rate back up by the term (as the checkout
233	  // total once did) silently drifts a cent or two from what the charge path
234	  // (lib/actions-hosting.ts's hostingChargeCents, same termPriceCents call)
235	  // actually bills. One rounding, at the total, shared with the charge path.
236	  const hostingTotalMatrix: Record<string, Record<number, number>> = {};
237	  // One month of the plan's own rate, credited when this customer still
238	  // qualifies — same shape as the VPS quote's `regularPlanCents - plan.priceCents`
239	  // (lib/order.ts), just carried alongside the matrix instead of computed by
240	  // a server round-trip. 0 (no credit) once first_month_free is off, already
241	  // claimed on this account/IP, or the plan changes and this needs recomputing.
242	  const hostingFirstMonthFreeCents: Record<string, number> = {};
243	  for (const h of hostingPlans) {
244	    hostingMatrix[h.id] = {};
245	    hostingTotalMatrix[h.id] = {};
246	    for (const t of VPS_TERMS) {
247	      const totalCents = termPriceCents(h.priceCents, t.months, annualPct);
248	      hostingTotalMatrix[h.id][t.months] = totalCents;
249	      hostingMatrix[h.id][t.months] = Math.round(totalCents / t.months);
250	    }
251	    hostingFirstMonthFreeCents[h.id] = hostingPromoEligible ? h.priceCents : 0;
252	  }
253	  const emailMatrix: Record<string, Record<number, number>> = {};
254	  const emailTotalMatrix: Record<string, Record<number, number>> = {};
255	  for (const e of emailPlans) {
256	    emailMatrix[e.id] = {};
257	    emailTotalMatrix[e.id] = {};
258	    for (const t of VPS_TERMS) {
259	      const totalCents = termPriceCents(e.priceCents, t.months, annualPct);
260	      emailTotalMatrix[e.id][t.months] = totalCents;
261	      emailMatrix[e.id][t.months] = Math.round(totalCents / t.months);
262	    }
263	  }
264	
265	  const addonOptions: AddonOption[] = [
266	    { key: "backup", name: "Backup Plus", note: "Longer retention, more restore points", icon: "archive", monthlyCents: backupCents, free: false },
267	    { key: "ip", name: "Dedicated IP", note: "An address of your own", icon: "nodes", monthlyCents: ipCents, free: false },
268	    { key: "malware", name: "Malware scanning", note: "Scheduled scans and alerts", icon: "shieldcheck", monthlyCents: 0, free: true },
269	    { key: "docker", name: "Docker pre-installed", note: "Ready for containers on first boot", icon: "docker", monthlyCents: 0, free: true },
270	  ];
271	
272	  return (
273	    <DeployView
274	      cat={{
275	        plans: planOptions,
276	        games: gameFamilies,
277	        hosting: hostingOptions,
278	        email: emailOptions,
279	        hostingMatrix,
280	        hostingTotalMatrix,
281	        hostingFirstMonthFreeCents,
282	        emailMatrix,
283	        emailTotalMatrix,
284	        oses: osOptions,
285	        terms: termOptions,
286	        addons: addonOptions,
287	        // Only regions where a Node actually exists — the wizard can never sell a
288	        // location we cannot provision in.
289	        regions: regionsFrom(nodes),
290	        diskPerGbCents,
291	        walletCents: user.balanceCents,
292	      }}
293	      priceMatrix={priceMatrix}
294	      hostingMatrix={hostingMatrix}
295	      emailMatrix={emailMatrix}
296	      firstName={user.name.split(" ")[0]}
297	      /* Which payment methods to OFFER. Read from the same predicates the
298	         charge paths use, so a method is never shown unless the platform can
299	         actually take money through it. In this sandbox all three are false by
300	         design, which is why the wallet is the only way to pay here. */
301	      methods={{
302	        card: stripeConfigured(),
303	        paypal: paypalConfigured(),
304	        crypto: coinbaseConfigured(),
305	      }}
306	      /* PayPal's PUBLIC client id. Safe to send to the browser — it is what the
307	         PayPal SDK script is keyed on and appears in every PayPal integration's
308	         page source. The SECRET stays on the server, where `createPayPalOrder`
309	         uses it. Null unless PayPal is actually configured, so the wizard can
310	         never mount the SDK against an empty id. */
311	      paypalClientId={paypalConfigured() ? process.env.PAYPAL_CLIENT_ID ?? null : null}
312	      fromCents={{
313	        vps: plans[0]?.priceCents ?? null,
314	        game: gamePlans.length ? Math.min(...gamePlans.map((g) => g.priceCents)) : null,
315	        hosting: hostingPlans.length ? Math.min(...hostingPlans.map((h) => h.priceCents)) : null,
316	        email: emailPlans.length ? Math.min(...emailPlans.map((e) => e.priceCents)) : null,
317	        // No fixed plan row for domains — real price is a live per-TLD
318	        // registrar quote. 999 ($9.99) used to stand in here as a flat
319	        // guess; `null` renders this tile's existing "Pricing unavailable"
320	        // fallback instead of a number that isn't real.
321	        domains: null,
322	      }}
323	    />
324	  );
325	}
