2169:export function DeployView({ cat, priceMatrix, hostingMatrix, emailMatrix, fromCents, methods, paypalClientId }: {

1	/* The shapes the deploy wizard renders.
2	 *
3	 * Every money field below is CENTS, ALREADY COMPUTED BY THE SERVER. The wizard
4	 * never multiplies, discounts or prorates — it prints. That is the whole point
5	 * of these types: they make it impossible for a component to be handed a raw
6	 * rate and be tempted to do the arithmetic itself, which is how a display price
7	 * and a charged price drift apart.
8	 *
9	 * If a screen needs a number that isn't here, add it to the server page and
10	 * pass it down — do not compute it in a component.
11	 */
12	
13	export type PlanOption = {
14	  id: string;
15	  slug: string;
16	  name: string;
17	  cpuCores: number;
18	  ramMB: number;
19	  diskGB: number;
20	  bandwidthTB: number;
21	  /** Regular monthly rate, for the struck-through "was" figure. */
22	  monthlyCents: number;
23	  /**
24	   * Effective monthly rate at the CURRENTLY SELECTED term, computed server-side
25	   * from the same annual-discount basis the charge path uses. Recomputed by the
26	   * server when the term changes — never derived here.
27	   */
28	  effectiveMonthlyCents: number;
29	  /** Set when the plan carries an intro rate, so the copy can be honest. */
30	  introMonthlyCents: number | null;
31	  introRenewalMonthlyCents: number | null;
32	  recommended?: boolean;
33	};
34	
35	export type OsOption = {
36	  id: string;
37	  name: string;
38	  version: string;
39	  /** Icon key in the interface sprite sheet. */
40	  icon: string;
41	  /** Which tab it belongs under in the Server settings panel. */
42	  category: "PLAIN_OS" | "CONTROL_PANEL" | "APPLICATION";
43	  /**
44	   * `ubuntu` | `debian` | `almalinux` | `rocky` | ... — the platform's own
45	   * grouping key. Each OsTemplate row is ONE VERSION; the design shows a card
46	   * per family with its versions as chips underneath, which is exactly what
47	   * this field already expresses.
48	   */
49	  family: string;
50	  /**
51	   * Key into the third-party mark sheet, when one exists. Control panels and
52	   * applications have their own drawn marks; the interface icon set has no
53	   * cPanel or WordPress glyph, so without this every one of them renders as the
54	   * same generic cube. Null for plain OS, which uses the interface set.
55	   */
56	  spriteKey: string | null;
57	};
58	
59	export type TermOption = {
60	  months: number;
61	  label: string;
62	  /** Discount percent applied at this term, server-supplied. */
63	  discountPercent: number;
64	};
65	
66	export type AddonOption = {
67	  key: "backup" | "malware" | "docker" | "ip";
68	  name: string;
69	  note: string;
70	  icon: string;
71	  /** Zero means genuinely included, not "price unknown". */
72	  monthlyCents: number;
73	  free: boolean;
74	};
75	
76	/** What the sticky cart shows. Comes straight from `quoteOrder`. */
77	export type CartPrice = {
78	  totalCents: number;
79	  months: number;
80	  regularPlanCents: number;
81	  promoName: string;
82	  promoCreditCents: number;
83	  couponLabel: string | null;
84	  couponDiscountCents: number;
85	  couponError: string | null;
86	  introRenewalMonthly: number | null;
87	} | null;
88	
89	
90	/* ── game ─────────────────────────────────────────────────────────────────
91	   A family is what the customer picks; a TIER is what they buy. Each GamePlan
92	   row is one tier of one family, so the picker is two levels and the money only
93	   attaches at the second. */
94	
95	export type GameTier = {
96	  id: string;
97	  name: string;
98	  ramMB: number;
