435	     * wizard. A customer could jump straight to Payment from step 1 and meet a
436	     * panel telling them to finish steps they had skipped past, with nothing
437	     * saying which field. Going BACK is unaffected: earlier steps are done, so
438	     * they stay live.
439	     *
440	     * Deploy is an OUTCOME, not a step you can choose. Leaving it live made it
441	     * clickable, which walked the customer into an empty slide describing
442	     * something that had not happened. It is reached by completing payment or
443	     * not at all. */
444	    const sections: Section[] = raw.map((s, i) => ({
445	      ...s,
446	      live: s.key === "deploy" ? false : i === 0 || raw.slice(0, i).every((p) => p.done),
447	    }));
448	    const firstOpen = raw.findIndex((s) => !s.done);
449	
450	    return {
451	      o, set, chooseService, chooseGame, toggleAddon, reset: () => setO(EMPTY),
452	      cat, plan, game, price, pricing, priceError,
453	      walletApplied,
454	      cardDue: due - walletApplied,
455	      sections,
456	      activeIdx: firstOpen === -1 ? raw.length - 1 : firstOpen,
457	    };
458	  }, [o, cat, plan, game, price, pricing, priceError, set, chooseService, chooseGame, toggleAddon]);
459	
460	  return <C.Provider value={v}>{children}</C.Provider>;
461	}
