45	/**
46	 * Confines the admin/staff hostnames to exactly their own portal.
47	 *
48	 * app/admin/layout.tsx and app/staff/layout.tsx already refuse the WRONG
49	 * direction -- /admin and /staff 404 on any host that isn't their own
50	 * NXEON_ADMIN_HOSTS/NXEON_STAFF_HOSTS. But nothing stopped the REVERSE: the
51	 * admin/staff hostnames proxy to the exact same Next.js backend as the main
52	 * site, so /dashboard, /login, /register, and every marketing page were
53	 * equally reachable there too -- confirmed live 2026-09-02, a customer's full
54	 * dashboard (wallet, deploy, domains) loading on the staff-only subdomain.
55	 * Not a data leak (they only ever saw their own account), but it defeats the
56	 * point of a separate, minimal, operations-only surface, and reduces
57	 * whatever "hard to guess" value the admin subdomain has by leaving it fully
58	 * browsable/indexable as a second copy of the public site.
59	 *
60	 * Together with the two layouts' existing checks this makes the mapping
61	 * exact: admin host <-> /admin only, staff host <-> /staff only, every other
62	 * host <-> everything except /admin and /staff.
63	 */
64	export function middleware(req: NextRequest) {
65	  const host = (req.headers.get("host") ?? "").toLowerCase().split(":")[0];
66	  const { pathname } = req.nextUrl;
67	
68	  const adminHosts = hostList(process.env.NXEON_ADMIN_HOSTS);
69	  const staffHosts = hostList(process.env.NXEON_STAFF_HOSTS);
70	  const isAdminHost = adminHosts.length > 0 && adminHosts.includes(host);
71	  const isStaffHost = staffHosts.length > 0 && staffHosts.includes(host);
72	
73	  // An admin impersonating a customer (lib/auth.ts's setImpersonation) needs to
74	  // browse the FULL customer app -- /dashboard, /checkout, etc. -- from their own
75	  // admin host, since impersonation swaps identity without changing host. Only
76	  // ADMIN can ever hold this cookie (EMPLOYEE/staff can never impersonate -- see
77	  // setImpersonation's own role check), so this only ever loosens the admin
78	  // host. We only check the cookie's PRESENCE here, not its signature/validity
79	  // -- that's exactly as strong as this gate needs to be: a forged or expired
80	  // token still gets fully re-verified by impersonating()/currentUser() at the
81	  // page/action layer, so a bad cookie here just falls back to "no session",
82	  // never to unauthorized access.
83	  const impCookieName = `${process.env.NXEON_COOKIE_NAME ?? "nxeon_session"}_imp`;
84	  const isImpersonating = isAdminHost && req.cookies.has(impCookieName);
85	
86	  if ((isAdminHost || isStaffHost) && !isImpersonating) {
87	    const ownPrefix = isAdminHost ? "/admin" : "/staff";
88	    const ownLogin = isAdminHost ? "/admin/login" : "/staff/login";
89	
90	    if (!isUniversallyAllowed(pathname) && !pathname.startsWith(ownPrefix)) {
91	      // The shared /login page (and any stray redirect to it -- logout()
92	      // always sends there, regardless of who's logging out) lands on this
93	      // host's own dedicated login instead of 404ing a signed-out visitor.
94	      if (pathname === "/login") {
95	        const url = req.nextUrl.clone();
96	        url.pathname = ownLogin;
97	        return NextResponse.redirect(url);
98	      }
99	      // The bare root -- where someone typing/bookmarking just the hostname
100	      // lands -- goes to the portal itself rather than 404ing. The admin
101	      // vhost happens to have its own nginx-level `location = / return 302
102	      // /admin` that already covered this there (confirmed live), but the
103	      // staff vhost has no equivalent, so its root 404'd under this same
104	      // isolation logic. Handling it here covers both hosts the same way
105	      // regardless of nginx config: an authenticated visit shows the portal,
106	      // an unauthenticated one gets bounced on to ownLogin by the layout's
107	      // own existing redirect -- no new auth logic needed either way.
108	      if (pathname === "/") {
109	        const url = req.nextUrl.clone();
110	        url.pathname = ownPrefix;
111	        return NextResponse.redirect(url);
112	      }
113	      return new NextResponse("Not found.", { status: 404 });
114	    }
115	  }
116	
117	  // Server Components have no built-in way to read the current pathname --
118	  // app/admin/layout.tsx and app/staff/layout.tsx need it to special-case
119	  // their own /login sub-route (public, no Shell, no auth redirect) without
120	  // a redirect loop. Set on the REQUEST (not the response) so headers() in a
121	  // downstream Server Component actually sees it.
122	  const requestHeaders = new Headers(req.headers);
123	  requestHeaders.set("x-pathname", pathname);
124	  return NextResponse.next({ request: { headers: requestHeaders } });
125	}
