/**
 * The full seed for a freshly-chosen service — same defaults `chooseService`
 * has always set (a complete, immediately-priceable order with only free
 * defaults ticked), pulled out as a pure function so `orderFromIntent` below
 * can start from the identical baseline before layering a marketing button's
 * specific selections on top. Takes the PREVIOUS order as `base` only so
 * fields the picker doesn't own (nothing today) would survive a re-seed —
 * `chooseService` and `orderFromIntent` both currently pass a full record in.
 */
function seedOrder(base: Order, cat: Catalog, k: ServiceKey): Order {
  const rec = cat.plans.find((p) => p.recommended) ?? cat.plans[0];
  return {
    ...base,
    service: k,
    planId: k === "vps" ? rec?.id ?? null : null,
    region: cat.regions[0]?.key ?? null,
