/** Reads a `DeployIntent` back off the URL, using the exact keys
 *  `lib/deploy-intent.ts`'s `deployHref` wrote — see that file for why each
 *  field has the query key it has. */
function parseIntent(sp: URLSearchParams): DeployIntent {
  const raw = (k: keyof DeployIntent) => sp.get(DEPLOY_PARAM[k]);
  const num = (k: keyof DeployIntent) => {
    const v = raw(k);
    if (!v) return undefined;
    const n = Number(v);
    return Number.isFinite(n) ? n : undefined;
  };
  const serviceRaw = raw("service");
  const service: DeployService | undefined =
    serviceRaw === "vps" || serviceRaw === "game" || serviceRaw === "hosting" || serviceRaw === "email"
      ? serviceRaw
      : undefined;
  const addonsRaw = raw("addons");
  return {
    service,
    planId: raw("planId") ?? undefined,
    termMonths: num("termMonths"),
    region: raw("region") ?? undefined,
    addons: addonsRaw ? addonsRaw.split(",").map((s) => s.trim()).filter(Boolean) : undefined,
    diskGb: num("diskGb"),
    gameFamily: raw("gameFamily") ?? undefined,
    gamePlanId: raw("gamePlanId") ?? undefined,
    gameVariant: raw("gameVariant") ?? undefined,
    players: num("players"),
    hostingPlanId: raw("hostingPlanId") ?? undefined,
    emailPlanId: raw("emailPlanId") ?? undefined,
  };
}

/** The tier that best fits a desired headcount: the smallest slotted tier
 *  that still covers it, or — past the top of the ladder, or when the family
 *  has no slotted tiers at all — the single most expensive one, the closest
 *  real thing this family sells to "give me your biggest". Same judgment call
 *  GameLandingCombined's own player-count slider already makes, just applied
 *  against the LIVE catalogue instead of that page's illustrative fixture. */
function nearestTierBySlots(tiers: GameTier[], players: number): string | null {
  if (tiers.length === 0) return null;
  const slotted = tiers.filter((t): t is GameTier & { slots: number } => t.slots != null);
  const fits = slotted.filter((t) => t.slots >= players).sort((a, b) => a.slots - b.slots)[0];
  if (fits) return fits.id;
  const pool = slotted.length ? slotted : tiers;
  return [...pool].sort((a, b) => a.monthlyCents - b.monthlyCents).at(-1)?.id ?? null;
}

/**
 * Materializes a `DeployIntent` into a real, catalogue-validated `Order` —
 * every id is checked against `cat` before it's used, so a stale or tampered
 * query string (an old link to a plan that's since been deactivated, say)
 * degrades to `seedOrder`'s normal defaults for whatever field didn't match,
 * never to a broken or half-filled order. Returns null when the URL carries
 * no recognised `product`, so the wizard opens on its ordinary empty first
 * step exactly as it always has.
 */
function orderFromIntent(cat: Catalog, intent: DeployIntent): Order | null {
  if (!intent.service) return null;
  const o = seedOrder(EMPTY, cat, intent.service);

  const term = intent.termMonths;
  if (term != null && cat.terms.some((t) => t.months === term)) o.termMonths = term;

  if (intent.service === "vps") {
    if (intent.planId && cat.plans.some((p) => p.id === intent.planId)) o.planId = intent.planId;
    if (intent.region && cat.regions.some((r) => r.key === intent.region)) o.region = intent.region;
    if (intent.addons?.length) {
      const valid = new Set(cat.addons.map((a) => a.key));
      const picked = intent.addons.filter((a) => valid.has(a));
      if (picked.length) o.addons = picked;
    }
    if (intent.diskGb != null && intent.diskGb >= 0) o.diskGb = Math.round(intent.diskGb);
  }

  if (intent.service === "game") {
    const g = intent.gameFamily ? cat.games.find((x) => x.family === intent.gameFamily) : null;
    if (g) {
      o.gameFamily = g.family;
      const exact = intent.gamePlanId ? g.tiers.find((t) => t.id === intent.gamePlanId) : null;
      o.gamePlanId =
        exact?.id
        ?? (intent.players && intent.players > 0 ? nearestTierBySlots(g.tiers, intent.players) : null)
        ?? [...g.tiers].sort((a, b) => a.monthlyCents - b.monthlyCents)[0]?.id
        ?? null;
      o.gameVariant =
        intent.gameVariant && g.variants.some((v) => v.id === intent.gameVariant)
          ? intent.gameVariant
          : g.defaultVariant;
    }
  }

  if (intent.service === "hosting" && intent.hostingPlanId && cat.hosting.some((h) => h.id === intent.hostingPlanId)) {
    o.hostingPlanId = intent.hostingPlanId;
  }

  if (intent.service === "email" && intent.emailPlanId && cat.email.some((e) => e.id === intent.emailPlanId)) {
    o.emailPlanId = intent.emailPlanId;
  }

  return o;
}

